const int first_n = (linear / group_size) * T::SWIZZLE_GROUP_N;
const int remaining_n = grid_n - first_n;
const int actual_n = remaining_n < T::SWIZZLE_GROUP_N ? remaining_n : T::SWIZZLE_GROUP_N;
