} else if (grid_n <= T::SWIZZLE_MAX_GRID_N && total > T::SWIZZLE_MIN_TILES) {
const unsigned partitions = ((grid_n <= T::SWIZZLE_SMALL_GRID_N && total < T::SWIZZLE_SMALL_TILES) ||
