const int col = block_n * T::B_N;
const int batch_id = block_id_z();
const int loops = T::FIXED_K ? T::FIXED_K / T::B_K : kargs.k / T::B_K;
auto g_a = make_gmem(reinterpret_cast<const D_A*>(kargs.ptr_a) + batch_id * kargs.stride_a_batch + row * (T::STATIC_STRIDE_K ? T::STATIC_STRIDE_K : kargs.stride_a),
static_cast<unsigned>((shape_m - row) * (T::STATIC_STRIDE_K ? T::STATIC_STRIDE_K : kargs.stride_a)));
