if constexpr (T::ENABLE_N_SWIZZLE) {
if (kargs.n / T::B_N >= T::SWIZZLE_MIN_N_TILES && kargs.m > T::B_M) {
const int grid_m = 1 + (kargs.m - 1) / T::B_M;
