static_for<T::E_M * T::E_N>([&](auto c_i) { stage_output_fragment(c_i); });
s_waitcnt_lgkmcnt(0_I);
__builtin_amdgcn_s_barrier();
static_for<T::OUTPUT_PASSES>([&](auto copy_i) { copy_output_bf16(copy_i); });
}
#endif

#endif
}
